-- The professors of the 2026-B sections as the catalog seed has them (qone-catalog-db V014, the
-- identity seed's ids): Carlos Ramírez ...221, Ana Torres ...222, Jorge Medina ...223. Idempotent.
UPDATE enrollment.catalog_section_view v SET professor_id = s.professor_id::uuid
FROM (VALUES
    ('55555555-5555-4555-8555-555555555501', '22222222-2222-4222-8222-222222222222'),
    ('55555555-5555-4555-8555-555555555502', '22222222-2222-4222-8222-222222222223'),
    ('55555555-5555-4555-8555-555555555503', '22222222-2222-4222-8222-222222222222'),
    ('55555555-5555-4555-8555-555555555504', '22222222-2222-4222-8222-222222222223'),
    ('55555555-5555-4555-8555-555555555505', '22222222-2222-4222-8222-222222222221'),
    ('55555555-5555-4555-8555-555555555506', '22222222-2222-4222-8222-222222222222'),
    ('55555555-5555-4555-8555-555555555507', '22222222-2222-4222-8222-222222222223'),
    ('55555555-5555-4555-8555-555555555508', '22222222-2222-4222-8222-222222222221'),
    ('55555555-5555-4555-8555-555555555509', '22222222-2222-4222-8222-222222222221'),
    ('55555555-5555-4555-8555-555555555510', '22222222-2222-4222-8222-222222222222'),
    ('55555555-5555-4555-8555-555555555511', '22222222-2222-4222-8222-222222222223')
) AS s (section_id, professor_id)
WHERE v.section_id = s.section_id::uuid;
